359:     // 1. Live Telemetry Real-time Jitter / Ticking Simulation
360:     const loadMetricEl = document.getElementById('loadMetricVal');
361:     const latencyJitterEl = document.getElementById('latencyJitter');
362: 
363:     let baseLoad = 1841;
364:     setInterval(() => {
365:       // Load variation (+/- 6 kW)
366:       const deltaLoad = Math.floor(Math.random() * 9) - 4;
367:       baseLoad = Math.max(1810, Math.min(1875, baseLoad + deltaLoad));
368:       if (loadMetricEl) {
369:         loadMetricEl.textContent = baseLoad.toLocaleString();
370:         loadMetricEl.classList.add('text-emerald-300');
371:         setTimeout(() => loadMetricEl.classList.remove('text-emerald-300'), 300);
372:       }
373: 
374:       // Latency jitter (19ms - 26ms)
375:       if (latencyJitterEl && Math.random() > 0.4) {
376:         const ms = 19 + Math.floor(Math.random() * 8);
377:         latencyJitterEl.textContent = `${ms}ms`;
378:       }
