381:     // 2. Interactive Chart Hover & Cursor Tracking
382:     const chartContainer = document.getElementById('chartContainer');
383:     const inspectPoint = document.getElementById('inspectPoint');
384:     const inspectLine = document.getElementById('inspectLine');
385:     const tooltipTime = document.getElementById('tooltipTime');
386:     const tooltipActual = document.getElementById('tooltipActual');
387:     const tooltipBaseline = document.getElementById('tooltipBaseline');
388:     const tooltipShaved = document.getElementById('tooltipShaved');
389:     const tooltipDelta = document.getElementById('tooltipDelta');
390: 
391:     const timelineData = [
392:       { xPct: 0.1, time: '02:00 (Off-Peak)', act: '1,120 kW', base: '1,140 kW', shave: '-20 kW', delta: '-1.8%' },
393:       { xPct: 0.25, time: '06:00 (Ramp-Up)', act: '1,450 kW', base: '1,510 kW', shave: '-60 kW', delta: '-4.0%' },
394:       { xPct: 0.47, time: '14:00 (Peak Window)', act: '1,940 kW', base: '2,180 kW', shave: '-240 kW', delta: '-11.0%' },
395:       { xPct: 0.67, time: '16:00 (BESS Shave)', act: '1,890 kW', base: '2,240 kW', shave: '-350 kW', delta: '-15.6%' },
396:       { xPct: 0.85, time: '20:30 (Evening)', act: '1,380 kW', base: '1,420 kW', shave: '-40 kW', delta: '-2.8%' }
397:     ];
398: 
399:     if (chartContainer) {
400:       chartContainer.addEventListener('mousemove', (e) => {
401:         const rect = chartContainer.getBoundingClientRect();
402:         const mouseX = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
403:         const pct = mouseX / rect.width;
404:         
405:         let nearest = timelineData[0];
406:         let minDist = Infinity;
407:         timelineData.forEach(pt => {
408:           const dist = Math.abs(pt.xPct - pct);
409:           if (dist < minDist) {
410:             minDist = dist;
411:             nearest = pt;
412:           }
413:         });
414: 
415:         const svgX = nearest.xPct * 600;
416:         if (inspectLine) {
417:           inspectLine.setAttribute('x1', svgX);
418:           inspectLine.setAttribute('x2', svgX);
419:         }
420:         if (inspectPoint) {
421:           inspectPoint.classList.remove('opacity-0');
422:           inspectPoint.setAttribute('cx', svgX);
423:           const approxY = 150 - (Math.sin(nearest.xPct * Math.PI) * 70);
424:           inspectPoint.setAttribute('cy', approxY);
425:         }
426: 
427:         if (tooltipTime) tooltipTime.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-emerald-400"></span> ${nearest.time}`;
428:         if (tooltipActual) tooltipActual.textContent = nearest.act;
429:         if (tooltipBaseline) tooltipBaseline.textContent = nearest.base;
430:         if (tooltipShaved) tooltipShaved.textContent = nearest.shave;
431:         if (tooltipDelta) tooltipDelta.textContent = `${nearest.delta} Delta`;
432:       });
433: 
434:       chartContainer.addEventListener('mouseleave', () => {
435:         if (inspectPoint) inspectPoint.classList.add('opacity-0');
436:         if (inspectLine) {
437:           inspectLine.setAttribute('x1', '280');
438:           inspectLine.setAttribute('x2', '280');
439:         }
440:         if (tooltipTime) tooltipTime.innerHTML = `<span class="w-1.5 h-1.5 rounded-full bg-emerald-400"></span> 14:00 (Peak Window)`;
441:         if (tooltipActual) tooltipActual.textContent = '1,940 kW';
442:         if (tooltipBaseline) tooltipBaseline.textContent = '2,180 kW';
443:         if (tooltipShaved) tooltipShaved.textContent = '-240 kW';
444:         if (tooltipDelta) tooltipDelta.textContent = '-11.0% Delta';
445:       });
446:     }
