// API Client - Centralized HTTP client for backend communication

const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL || 'http://localhost:8000';
const DEFAULT_TIMEOUT = 30000;

export class ApiError extends Error {
  constructor(
    public readonly code: string,
    public readonly message: string,
    public readonly statusCode: number,
    public readonly details?: Record<string, unknown>,
    public readonly timestamp: string = new Date().toISOString(),
    public readonly requestId?: string
  ) {
    super(message);
    this.name = 'ApiError';
  }

  static fromResponse(response: Response, data: unknown): ApiError {
    const errorData = data as Record<string, unknown> | undefined;
    return new ApiError(
      (errorData?.code as string) || `HTTP_${response.status}`,
      (errorData?.message as string) || response.statusText,
      response.status,
      errorData?.details as Record<string, unknown>,
      (errorData?.timestamp as string) || new Date().toISOString(),
      (errorData?.requestId as string) || undefined
    );
  }
}

interface RequestOptions extends RequestInit {
  timeout?: number;
  params?: Record<string, string | number | boolean | undefined>;
}

function buildUrl(endpoint: string, params?: Record<string, string | number | boolean | undefined>): string {
  const url = new URL(`${API_BASE_URL}${endpoint}`);
  if (params) {
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        url.searchParams.append(key, String(value));
      }
    });
  }
  return url.toString();
}

async function fetchWithTimeout(url: string, options: RequestOptions = {}): Promise<Response> {
  const { timeout = DEFAULT_TIMEOUT, ...fetchOptions } = options;
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);

  try {
    const response = await fetch(url, {
      ...fetchOptions,
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
        ...fetchOptions.headers,
      },
    });
    return response;
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      throw new ApiError('TIMEOUT', 'Request timed out', 408);
    }
    throw new ApiError('NETWORK_ERROR', 'Network request failed', 0);
  } finally {
    clearTimeout(timeoutId);
  }
}

export async function apiGet<T>(endpoint: string, params?: Record<string, string | number | boolean | undefined>): Promise<T> {
  const url = buildUrl(endpoint, params);
  const response = await fetchWithTimeout(url, { method: 'GET' });

  if (!response.ok) {
    const data = await response.json().catch(() => ({}));
    throw ApiError.fromResponse(response, data);
  }

  return response.json();
}

export async function apiPost<T>(endpoint: string, body: unknown): Promise<T> {
  const url = buildUrl(endpoint);
  const response = await fetchWithTimeout(url, {
    method: 'POST',
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const data = await response.json().catch(() => ({}));
    throw ApiError.fromResponse(response, data);
  }

  return response.json();
}

export async function apiPut<T>(endpoint: string, body: unknown): Promise<T> {
  const url = buildUrl(endpoint);
  const response = await fetchWithTimeout(url, {
    method: 'PUT',
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const data = await response.json().catch(() => ({}));
    throw ApiError.fromResponse(response, data);
  }

  return response.json();
}

export async function apiDelete<T>(endpoint: string): Promise<T> {
  const url = buildUrl(endpoint);
  const response = await fetchWithTimeout(url, { method: 'DELETE' });

  if (!response.ok) {
    const data = await response.json().catch(() => ({}));
    throw ApiError.fromResponse(response, data);
  }

  return response.json();
}

