// Custom Hooks for Data Fetching
// Using React's built-in state management with SWR-like patterns

import { useState, useEffect, useCallback, useRef } from 'react';
import type { ApiError } from '@/services/api-client';

// Generic fetch hook with caching and deduplication
interface UseFetchOptions<T> {
  enabled?: boolean;
  revalidateOnFocus?: boolean;
  revalidateOnReconnect?: boolean;
  dedupeInterval?: number;
  onSuccess?: (data: T) => void;
  onError?: (error: ApiError) => void;
}

interface UseFetchResult<T> {
  data: T | null;
  error: ApiError | null;
  isLoading: boolean;
  isError: boolean;
  isSuccess: boolean;
  mutate: (newData?: T | ((old: T | null) => T)) => Promise<T | null>;
  refetch: () => Promise<void>;
}

const cache = new Map<string, { data: unknown; timestamp: number; promise: Promise<unknown> | null }>();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

function generateCacheKey(endpoint: string, params?: Record<string, unknown>): string {
  return `${endpoint}?${new URLSearchParams(params as Record<string, string>).toString()}`;
}

export function useFetch<T>(
  endpoint: string,
  params?: Record<string, unknown>,
  options: UseFetchOptions<T> = {}
): UseFetchResult<T> {
  const {
    enabled = true,
    revalidateOnFocus = false,
    revalidateOnReconnect = false,
    dedupeInterval = 1000,
    onSuccess,
    onError,
  } = options;

  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isError, setIsError] = useState(false);

  const cacheKey = generateCacheKey(endpoint, params);
  const abortControllerRef = useRef<AbortController | null>(null);
  const mountedRef = useRef(true);

  const fetchData = useCallback(async (force = false) => {
    if (!enabled) return;

    const cached = cache.get(cacheKey);
    const now = Date.now();

    // Return cached data if valid and not forcing refresh
    if (!force && cached && now - cached.timestamp < CACHE_TTL) {
      if (cached.promise) {
        try {
          const result = await cached.promise;
          if (mountedRef.current) {
            setData(result as T);
            setIsSuccess(true);
            setIsError(false);
            setError(null);
            onSuccess?.(result as T);
          }
          return result as T;
        } catch {
          // Fall through to refetch
        }
      }
    }

    // Check for in-flight request
    if (cached?.promise && !force) {
      try {
        const result = await cached.promise;
        if (mountedRef.current) {
          setData(result as T);
          setIsSuccess(true);
          setIsError(false);
          setError(null);
          onSuccess?.(result as T);
        }
        return result as T;
      } catch {
        // Fall through to new request
      }
    }

    // Create new request
    abortControllerRef.current?.abort();
    abortControllerRef.current = new AbortController();

    setIsLoading(true);
    setIsError(false);
    setError(null);

    try {
      const response = await fetch(`${process.env.NEXT_PUBLIC_API_BASE_URL || 'http://localhost:8000'}${endpoint}?${new URLSearchParams(params as Record<string, string>).toString()}`, {
        signal: abortControllerRef.current.signal,
        headers: { 'Content-Type': 'application/json' },
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new ApiError(
          (errorData.code as string) || `HTTP_${response.status}`,
          (errorData.message as string) || response.statusText,
          response.status,
          errorData.details as Record<string, unknown>,
          (errorData.timestamp as string) || new Date().toISOString(),
          (errorData.requestId as string) || undefined
        );
      }

      const result = await response.json();

      if (mountedRef.current) {
        setData(result);
        setIsSuccess(true);
        setIsError(false);
        setError(null);
        onSuccess?.(result);
      }

      // Update cache
      cache.set(cacheKey, { data: result, timestamp: now, promise: null });
      return result;
    } catch (err) {
      if (err instanceof DOMException && err.name === 'AbortError') {
        return data;
      }

      const apiError = err instanceof ApiError ? err : new ApiError('UNKNOWN', String(err), 0);

      if (mountedRef.current) {
        setError(apiError);
        setIsError(true);
        setIsSuccess(false);
        onError?.(apiError);
      }
      throw apiError;
    } finally {
      if (mountedRef.current) {
        setIsLoading(false);
      }
    }
  }, [cacheKey, enabled, onSuccess, onError, params]);

  const mutate = useCallback(async (newData?: T | ((old: T | null) => T)) => {
    const resolvedData = typeof newData === 'function' ? (newData as (old: T | null) => T)(data) : newData;

    if (resolvedData !== undefined) {
      setData(resolvedData);
      cache.set(cacheKey, { data: resolvedData, timestamp: Date.now(), promise: null });
    }

    return resolvedData ?? data;
  }, [cacheKey, data]);

  const refetch = useCallback(async () => {
    await fetchData(true);
  }, [fetchData]);

  // Initial fetch
  useEffect(() => {
    mountedRef.current = true;
    if (enabled) {
      fetchData();
    }
    return () => {
      mountedRef.current = false;
    };
  }, [fetchData, enabled]);

  // Revalidate on focus
  useEffect(() => {
    if (!revalidateOnFocus) return;

    const handleFocus = () => {
      if (mountedRef.current && !isLoading) {
        fetchData(true);
      }
    };

    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [revalidateOnFocus, fetchData, isLoading]);

  // Revalidate on reconnect
  useEffect(() => {
    if (!revalidateOnReconnect) return;

    const handleOnline = () => {
      if (mountedRef.current) {
        fetchData(true);
      }
    };

    window.addEventListener('online', handleOnline);
    return () => window.removeEventListener('online', handleOnline);
  }, [revalidateOnReconnect, fetchData]);

  return {
    data,
    error,
    isLoading,
    isError,
    isSuccess,
    mutate,
    refetch,
  };
}

// Mutation hook for POST/PUT/DELETE operations
interface UseMutationOptions<TData, TVariables> {
  onSuccess?: (data: TData, variables: TVariables) => void;
  onError?: (error: ApiError, variables: TVariables) => void;
  onSettled?: (data: TData | null, error: ApiError | null, variables: TVariables) => void;
}

interface UseMutationResult<TData, TVariables> {
  mutate: (variables: TVariables) => Promise<TData>;
  mutateAsync: (variables: TVariables) => Promise<TData>;
  data: TData | null;
  error: ApiError | null;
  isLoading: boolean;
  isError: boolean;
  isSuccess: boolean;
  reset: () => void;
}

export function useMutation<TData, TVariables>(
  mutationFn: (variables: TVariables) => Promise<TData>,
  options: UseMutationOptions<TData, TVariables> = {}
): UseMutationResult<TData, TVariables> {
  const [data, setData] = useState<TData | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [isError, setIsError] = useState(false);

  const mutate = useCallback(async (variables: TVariables) => {
    setIsLoading(true);
    setIsError(false);
    setIsSuccess(false);
    setError(null);

    try {
      const result = await mutationFn(variables);
      setData(result);
      setIsSuccess(true);
      options.onSuccess?.(result, variables);
      return result;
    } catch (err) {
      const apiError = err instanceof ApiError ? err : new ApiError('MUTATION_ERROR', String(err), 0);
      setError(apiError);
      setIsError(true);
      options.onError?.(apiError, variables);
      throw apiError;
    } finally {
      setIsLoading(false);
      options.onSettled?.(data, error, variables);
    }
  }, [mutationFn, options]);

  const reset = useCallback(() => {
    setData(null);
    setError(null);
    setIsLoading(false);
    setIsSuccess(false);
    setIsError(false);
  }, []);

  return {
    mutate,
    mutateAsync: mutate,
    data,
    error,
    isLoading,
    isError,
    isSuccess,
    reset,
  };
}

