// Energy-specific hooks

import { useState, useCallback, useMemo } from 'react';
import { useFetch } from './use-api';
import type { EnergyReading, EnergyAnalysis, TimeRange } from '@/types';
import { subDays, startOfDay, endOfDay, formatISO } from 'date-fns';

export function useEnergyReadings(
  buildingId: string | undefined,
  meterId: string | undefined,
  timeRange: TimeRange,
  customRange?: { start: Date; end: Date }
) {
  const [interval, setInterval] = useState<'15m' | '1h' | '1d'>('1h');

  const { start, end } = useMemo(() => {
    const now = new Date();
    switch (timeRange) {
      case '24h':
        return { start: subDays(now, 1), end: now };
      case '7d':
        return { start: subDays(now, 7), end: now };
      case '30d':
        return { start: subDays(now, 30), end: now };
      case '90d':
        return { start: subDays(now, 90), end: now };
      case 'custom':
        return customRange ? { start: customRange.start, end: customRange.end } : { start: subDays(now, 7), end: now };
      default:
        return { start: subDays(now, 7), end: now };
    }
  }, [timeRange, customRange]);

  const params = useMemo(() => ({
    buildingId,
    meterId,
    startDate: formatISO(startOfDay(start)),
    endDate: formatISO(endOfDay(end)),
    interval,
    limit: 2000,
  }), [buildingId, meterId, start, end, interval]);

  const { data, error, isLoading, refetch } = useFetch<EnergyReading[]>('/api/v1/energy/readings', params);

  return {
    readings: data || [],
    error,
    isLoading,
    refetch,
    interval,
    setInterval,
    dateRange: { start, end },
  };
}

export function useEnergyAnalysis(
  buildingId: string | undefined,
