// Chart data transformation
export function transformReadingsForChart(readings: EnergyReading[]): Array<{
  timestamp: string;
  value: number;
  label?: string;
  isForecast?: boolean;
  isAnomaly?: boolean;
}> {
  return readings
    .filter(r => r.value !== null && r.value !== undefined)
    .map(r => ({
      timestamp: r.timestamp,
      value: r.value,
      label: new Date(r.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      isForecast: false,
      isAnomaly: r.quality === 'questionable',
    }));
}

export function mergeForecastWithReadings(
  readings: EnergyReading[],
  forecast: Array<{ timestamp: string; predictedValue: number; lowerBound?: number; upperBound?: number }>
) {
  const readingMap = new Map(readings.map(r => [r.timestamp, r.value]));

  return forecast.map(f => ({
    timestamp: f.timestamp,
    value: f.predictedValue,
    label: new Date(f.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    isForecast: true,
    lowerBound: f.lowerBound,
    upperBound: f.upperBound,
    actualValue: readingMap.get(f.timestamp),
  }));
}

// Forecast-specific hooks

import { useState, useCallback, useMemo } from 'react';
import { useFetch, useMutation } from './use-api';
import type { ForecastRequest, ForecastResult, ForecastPoint } from '@/types';
import { subDays, startOfDay, endOfDay, formatISO } from 'date-fns';

export function useForecast(
  buildingId: string | undefined,
  meterId: string | undefined,
  horizonHours: number = 24
) {
  const [request, setRequest] = useState<ForecastRequest | null>(null);

  const params = useMemo(() => ({
    buildingId,
    meterId,
    horizonHours,
    includeConfidenceInterval: true,
  }), [buildingId, meterId, horizonHours]);

  const { data, error, isLoading, refetch } = useFetch<ForecastResult>('/api/v1/forecast', params, {
    enabled: !!buildingId && horizonHours > 0,
  });

  const updateHorizon = useCallback((hours: number) => {
    setRequest(prev => prev ? { ...prev, horizonHours: hours } : null);
  }, []);

  return {
    forecast: data,
    forecastPoints: data?.forecast || [],
    modelInfo: data?.modelInfo,
    dataQuality: data?.dataQuality,
    warnings: data?.warnings,
    error,
    isLoading,
    refetch,
    horizonHours,
    setHorizonHours: updateHorizon,
  };
}

