// Anomaly-specific hooks

import { useState, useCallback, useMemo } from 'react';
import { useFetch, useMutation } from './use-api';
import type { AnomalyRequest, AnomalyResult, Anomaly } from '@/types';
import { subDays, startOfDay, endOfDay, formatISO } from 'date-fns';

export function useAnomalies(
  buildingId: string | undefined,
  meterId: string | undefined,
  timeRange: '24h' | '7d' | '30d' | '90d' | 'custom',
  customRange?: { start: Date; end: Date },
  options?: { sensitivity?: AnomalyRequest['sensitivity']; minScore?: number }
) {
  const { start, end } = useMemo(() => {
    const now = new Date();
    switch (timeRange) {
      case '24h':
        return { start: subDays(now, 1), end: now };
      case '7d':
        return { start: subDays(now, 7), end: now };
      case '30d':
        return { start: subDays(now, 30), end: now };
      case '90d':
        return { start: subDays(now, 90), end: now };
      case 'custom':
        return customRange ? { start: customRange.start, end: customRange.end } : { start: subDays(now, 7), end: now };
      default:
        return { start: subDays(now, 7), end: now };
    }
  }, [timeRange, customRange]);

  const params = useMemo(() => ({
    buildingId,
    meterId,
    startDate: formatISO(startOfDay(start)),
    endDate: formatISO(endOfDay(end)),
    sensitivity: options?.sensitivity || 'medium',
    minScore: options?.minScore || 0.5,
  }), [buildingId, meterId, start, end, options?.sensitivity, options?.minScore]);

  const { data, error, isLoading, refetch } = useFetch<AnomalyResult>('/api/v1/anomalies/detect', params, {
    enabled: !!buildingId,
  });

  const updateAnomalyStatus = useMutation(
    (variables: { anomalyId: string; status: Anomaly['status'] }) =>
      import('@/services/anomaly-service').then(m => m.updateAnomalyStatus(variables.anomalyId, variables.status))
  );

  const filteredAnomalies = useMemo(() => {
    if (!data?.anomalies) return [];
    return data.anomalies;
  }, [data]);

  const anomaliesByStatus = useMemo(() => {
    const grouped: Record<Anomaly['status'], Anomaly[]> = {
      new: [],
      investigating: [],
      resolved: [],
      dismissed: [],
    };
    filteredAnomalies.forEach(a => {
      grouped[a.status].push(a);
    });
    return grouped;
  }, [filteredAnomalies]);

  const anomaliesBySeverity = useMemo(() => {
    const grouped: Record<Anomaly['severity'], Anomaly[]> = {
      low: [],
      medium: [],
      high: [],
      critical: [],
    };
    filteredAnomalies.forEach(a => {
      grouped[a.severity].push(a);
    });
    return grouped;
  }, [filteredAnomalies]);

  return {
    anomalies: filteredAnomalies,
    totalCount: data?.totalCount || 0,
    anomaliesByStatus,
    anomaliesBySeverity,
    detectionPeriod: data?.detectionPeriod,
    modelInfo: data?.modelInfo,
    error,
    isLoading,
    refetch,
    updateStatus: updateAnomalyStatus.mutate,
    isUpdatingStatus: updateAnomalyStatus.isLoading,
  };
}

