// Carbon-specific hooks

import { useState, useCallback, useMemo } from 'react';
import { useFetch, useMutation } from './use-api';
import type { CarbonSummaryRequest, CarbonSummary } from '@/types';
import { subDays, startOfDay, endOfDay, formatISO } from 'date-fns';

export function useCarbonSummary(
  buildingId: string | undefined,
  meterId: string | undefined,
  timeRange: '24h' | '7d' | '30d' | '90d' | 'custom',
  customRange?: { start: Date; end: Date },
  emissionFactorId?: string
) {
  const { start, end } = useMemo(() => {
    const now = new Date();
    switch (timeRange) {
      case '24h':
        return { start: subDays(now, 1), end: now };
      case '7d':
        return { start: subDays(now, 7), end: now };
      case '30d':
        return { start: subDays(now, 30), end: now };
      case '90d':
        return { start: subDays(now, 90), end: now };
      case 'custom':
        return customRange ? { start: customRange.start, end: customRange.end } : { start: subDays(now, 30), end: now };
      default:
        return { start: subDays(now, 30), end: now };
    }
  }, [timeRange, customRange]);

  const params = useMemo(() => ({
    buildingId,
    meterId,
    startDate: formatISO(startOfDay(start)),
    endDate: formatISO(endOfDay(end)),
    emissionFactorId,
  }), [buildingId, meterId, start, end, emissionFactorId]);

  const { data, error, isLoading, refetch } = useFetch<CarbonSummary>('/api/v1/carbon/summary', params, {
    enabled: !!buildingId,
  });

  const emissionFactors = useFetch<Array<{
    id: string;
    value: number;
    unit: string;
    source: string;
    sourceUrl: string;
    region: string;
    validFrom: string;
    validTo?: string;
    isDefault: boolean;
  }>>('/api/v1/carbon/factors');

  const setDefaultFactor = useMutation(
    (factorId: string) => import('@/services/carbon-service').then(m => m.setDefaultEmissionFactor(factorId))
  );

  const isFactorConfigured = !!data?.emissionFactor;
  const missingFactorMessage = !isFactorConfigured 
    ? 'No emission factor configured. Please configure an emission factor in settings to view carbon analytics.'
    : null;

  return {
    summary: data,
    totalEmissions: data?.totalEmissions || 0,
    emissionFactor: data?.emissionFactor,
    breakdown: data?.breakdown,
    trend: data?.trend,
    isEstimated: data?.isEstimated || false,
    isFactorConfigured,
    missingFactorMessage,
    error,
    isLoading,
    refetch,
    emissionFactors: emissionFactors.data || [],
    isLoadingFactors: emissionFactors.isLoading,
    setDefaultFactor: setDefaultFactor.mutate,
    isSettingFactor: setDefaultFactor.isLoading,
  };
}

// Scenario/Simulation-specific hooks

import { useState, useCallback, useMemo } from 'react';
import { useFetch, useMutation } from './use-api';
import type { ScenarioRequest, ScenarioResult, ScenarioAssumption } from '@/types';
import { subDays, startOfDay, endOfDay, formatISO } from 'date-fns';

export function useScenarioSimulation() {
  const [assumptions, setAssumptions] = useState<ScenarioAssumption[]>([]);
  const [baselinePeriod, setBaselinePeriod] = useState<{ start: Date; end: Date } | null>(null);
  const [buildingId, setBuildingId] = useState<string | undefined>(undefined);
  const [meterId, setMeterId] = useState<string | undefined>(undefined);

  const simulateScenario = useMutation(
    (request: ScenarioRequest) => import('@/services/scenario-service').then(m => m.simulateScenario(request))
  );

  const runSimulation = useCallback(async () => {
    if (!baselinePeriod || !buildingId) {
      throw new Error('Baseline period and building ID are required');
    }

    const request: ScenarioRequest = {
      buildingId,
      meterId,
      baselinePeriod: {
        start: formatISO(startOfDay(baselinePeriod.start)),
        end: formatISO(endOfDay(baselinePeriod.end)),
      },
      assumptions,
    };

    return simulateScenario.mutate(request);
  }, [baselinePeriod, buildingId, meterId, assumptions, simulateScenario]);

  const addAssumption = useCallback((assumption: Omit<ScenarioAssumption, 'id'>) => {
    const newAssumption: ScenarioAssumption = {
      ...assumption,
      id: crypto.randomUUID(),
    };
    setAssumptions(prev => [...prev, newAssumption]);
  }, []);

  const updateAssumption = useCallback((id: string, updates: Partial<ScenarioAssumption>) => {
    setAssumptions(prev => prev.map(a => a.id === id ? { ...a, ...updates } : a));
  }, []);

  const removeAssumption = useCallback((id: string) => {
    setAssumptions(prev => prev.filter(a => a.id !== id));
  }, []);

  const resetAssumptions = useCallback(() => {
    setAssumptions([]);
  }, []);

  const loadTemplates = useFetch<ScenarioAssumption[]>('/api/v1/scenarios/templates', {}, { enabled: false });

  const applyTemplate = useCallback((template: ScenarioAssumption) => {
    addAssumption({ ...template, id: crypto.randomUUID() });
  }, [addAssumption]);

  return {
    // State
    assumptions,
    baselinePeriod,
    buildingId,
    meterId,
    // Actions
    setBuildingId,
    setMeterId,
    setBaselinePeriod,
    addAssumption,
    updateAssumption,
    removeAssumption,
    resetAssumptions,
    runSimulation,
    // Results
    simulationResult: simulateScenario.data,
    isSimulating: simulateScenario.isLoading,
    simulationError: simulateScenario.error,
    // Templates
    templates: loadTemplates.data || [],
    isLoadingTemplates: loadTemplates.isLoading,
    loadTemplates: loadTemplates.refetch,
    applyTemplate,
    // Validation
    isValid: baselinePeriod !== null && buildingId !== undefined && assumptions.length > 0,
  };
}

export function useScenarioHistory(
  buildingId: string | undefined,
  params?: { limit?: number; offset?: number }
) {
  return useFetch<{ scenarios: ScenarioResult[]; total: number }>(
    '/api/v1/scenarios/history',
    { buildingId, ...params },
    { enabled: !!buildingId }
  );
}

// Formatters and utility functions

export function formatEnergy(value: number, unit: 'kWh' | 'kW' | 'MWh' = 'kWh', decimals: number = 1): string {
  if (value >= 1000000 && unit === 'kWh') {
    return `${(value / 1000000).toFixed(decimals)} MWh`;
  }
  if (value >= 1000 && unit === 'kWh') {
    return `${(value / 1000).toFixed(decimals)} MWh`;
  }
  if (value >= 1000 && unit === 'kW') {
    return `${(value / 1000).toFixed(decimals)} MW`;
  }
  return `${value.toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals })} ${unit}`;
}

export function formatNumber(value: number, decimals: number = 1): string {
  if (value >= 1000000) {
    return `${(value / 1000000).toFixed(decimals)}M`;
  }
  if (value >= 1000) {
    return `${(value / 1000).toFixed(decimals)}K`;
  }
  return value.toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
}

export function formatPercent(value: number, decimals: number = 1): string {
  const sign = value > 0 ? '+' : '';
  return `${sign}${value.toFixed(decimals)}%`;
}

export function formatCurrency(value: number, currency: string = 'USD', decimals: number = 0): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  }).format(value);
}

export function formatTimestamp(timestamp: string, options?: Intl.DateTimeFormatOptions): string {
  const date = new Date(timestamp);
  return date.toLocaleString('en-US', {
    dateStyle: 'short',
    timeStyle: 'short',
    ...options,
  });
}

export function formatDate(date: Date | string, options?: Intl.DateTimeFormatOptions): string {
  const d = typeof date === 'string' ? new Date(date) : date;
  return d.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    ...options,
  });
}

export function formatTime(date: Date | string, options?: Intl.DateTimeFormatOptions): string {
  const d = typeof date === 'string' ? new Date(date) : date;
  return d.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    ...options,
  });
}

export function formatRelativeTime(timestamp: string): string {
  const date = new Date(timestamp);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  const diffHours = Math.floor(diffMs / 3600000);
  const diffDays = Math.floor(diffMs / 86400000);

  if (diffMins < 1) return 'Just now';
  if (diffMins < 60) return `${diffMins}m ago`;
  if (diffHours < 24) return `${diffHours}h ago`;
  if (diffDays < 7) return `${diffDays}d ago`;
  return formatDate(date);
}

export function getTrendDirection(current: number, previous: number): 'up' | 'down' | 'stable' {
  const threshold = 0.01; // 1% threshold
  const change = (current - previous) / Math.abs(previous || 1);
  if (change > threshold) return 'up';
  if (change < -threshold) return 'down';
  return 'stable';
}

export function calculatePercentChange(current: number, previous: number): number {
  if (previous === 0) return current > 0 ? 100 : 0;
  return ((current - previous) / Math.abs(previous)) * 100;
}

export function getStatusColor(status: 'good' | 'warning' | 'critical' | 'unknown'): string {
  switch (status) {
    case 'good': return 'text-emerald-400';
    case 'warning': return 'text-amber-400';
    case 'critical': return 'text-rose-400';
    default: return 'text-slate-400';
  }
}

export function getStatusBg(status: 'good' | 'warning' | 'critical' | 'unknown'): string {
  switch (status) {
    case 'good': return 'bg-emerald-950/50 border-emerald-500/30';
    case 'warning': return 'bg-amber-950/50 border-amber-500/30';
    case 'critical': return 'bg-rose-950/50 border-rose-500/30';
    default: return 'bg-slate-950/50 border-slate-500/30';
  }
}

export function getSeverityColor(severity: string): string {
  switch (severity) {
    case 'low': return 'text-emerald-400 bg-emerald-950/50 border-emerald-500/30';
    case 'medium': return 'text-amber-400 bg-amber-950/50 border-amber-500/30';
    case 'high': return 'text-orange-400 bg-orange-950/50 border-orange-500/30';
    case 'critical': return 'text-rose-400 bg-rose-950/50 border-rose-500/30';
    default: return 'text-slate-400 bg-slate-950/50 border-slate-500/30';
  }
}

export function truncateText(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength - 3) + '...';
}

export function debounce<T extends (...args: unknown[]) => unknown>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout | null = null;
  return (...args: Parameters<T>) => {
    if (timeout) clearTimeout(timeout);
    timeout = setTimeout(() => func(...args), wait);
  };
}

export function classNames(...classes: (string | boolean | undefined | null)[]): string {
  return classes.filter(Boolean).join(' ');
}

// Validation utilities

import { z } from 'zod';

export const dateRangeSchema = z.object({
  start: z.date(),
  end: z.date(),
}).refine(data => data.start <= data.end, {
  message: 'Start date must be before end date',
  path: ['start'],
});

export const energyAnalysisSchema = z.object({
  buildingId: z.string().optional(),
  meterId: z.string().optional(),
  startDate: z.string().datetime(),
  endDate: z.string().datetime(),
  interval: z.enum(['15m', '1h', '1d']).optional(),
  aggregation: z.enum(['sum', 'mean', 'max']).optional(),
});

export const forecastSchema = z.object({
  buildingId: z.string().optional(),
  meterId: z.string().optional(),
  horizonHours: z.number().int().min(1).max(168), // Max 1 week
  includeConfidenceInterval: z.boolean().optional(),
});

export const anomalySchema = z.object({
  buildingId: z.string().optional(),
  meterId: z.string().optional(),
  startDate: z.string().datetime(),
  endDate: z.string().datetime(),
  sensitivity: z.enum(['low', 'medium', 'high']).optional(),
  minScore: z.number().min(0).max(1).optional(),
});

export const carbonSchema = z.object({
  buildingId: z.string().optional(),
  meterId: z.string().optional(),
  startDate: z.string().datetime(),
  endDate: z.string().datetime(),
  emissionFactorId: z.string().optional(),
});

export const scenarioAssumptionSchema = z.object({
  id: z.string(),
  name: z.string().min(1),
  description: z.string().optional(),
  reductionPercent: z.number().min(0).max(100),
  applicableHours: z.object({
    start: z.number().int().min(0).max(23),
    end: z.number().int().min(0).max(23),
    daysOfWeek: z.array(z.number().int().min(0).max(6)).optional(),
  }).optional(),
  costPerUnit: z.number().min(0).optional(),
  implementationCost: z.number().min(0).optional(),
});

export const scenarioSchema = z.object({
  buildingId: z.string().optional(),
  meterId: z.string().optional(),
  baselinePeriod: z.object({
    start: z.string().datetime(),
    end: z.string().datetime(),
  }),
  assumptions: z.array(scenarioAssumptionSchema).min(1, 'At least one assumption is required'),
});

export type EnergyAnalysisInput = z.infer<typeof energyAnalysisSchema>;
export type ForecastInput = z.infer<typeof forecastSchema>;
export type AnomalyInput = z.infer<typeof anomalySchema>;
export type CarbonInput = z.infer<typeof carbonSchema>;
export type ScenarioInput = z.infer<typeof scenarioSchema>;

export function validateEnergyAnalysis(input: unknown) {
  return energyAnalysisSchema.safeParse(input);
}

export function validateForecast(input: unknown) {
  return forecastSchema.safeParse(input);
}

export function validateAnomaly(input: unknown) {
  return anomalySchema.safeParse(input);
}

export function validateCarbon(input: unknown) {
  return carbonSchema.safeParse(input);
}

export function validateScenario(input: unknown) {
  return scenarioSchema.safeParse(input);
}

export function getValidationErrors(error: z.ZodError): Record<string, string> {
  const errors: Record<string, string> = {};
  error.errors.forEach(e => {
    const path = e.path.join('.');
    errors[path] = e.message;
  });
  return errors;
}

