// Badge Component
// Fluxora design system badges for status, labels, and indicators

import { classNames } from '@/lib/formatters';

export interface BadgeProps {
  children: React.ReactNode;
  variant?: 'default' | 'success' | 'warning' | 'danger' | 'info' | 'neutral' | 'champagne';
  size?: 'sm' | 'md' | 'lg';
  dot?: boolean;
  pulse?: boolean;
  className?: string;
  onClick?: () => void;
}

const variantStyles = {
  default: 'bg-brand-surfaceContainerHigh border border-brand-outlineVariant/30 text-brand-onSurfaceVariant',
  success: 'bg-emerald-950/60 border border-emerald-500/40 text-emerald-300',
  warning: 'bg-amber-950/60 border border-amber-500/40 text-amber-300',
  danger: 'bg-rose-950/60 border border-rose-500/40 text-rose-300',
  info: 'bg-blue-950/60 border border-blue-500/40 text-blue-300',
  neutral: 'bg-slate-950/60 border border-slate-500/40 text-slate-300',
  champagne: 'bg-brand-secondary/15 border border-brand-secondary/40 text-brand-secondary font-mono',
};

const sizeStyles = {
  sm: 'px-2 py-0.5 text-[10px] gap-1',
  md: 'px-2.5 py-1 text-[11px] gap-1.5',
  lg: 'px-3 py-1.5 text-xs gap-2',
};

export function Badge({
  children,
  variant = 'default',
  size = 'md',
  dot = false,
  pulse = false,
  className,
  onClick,
}: BadgeProps) {
  const Component = onClick ? 'button' : 'span';

  return (
    <Component
      className={classNames(
        'inline-flex items-center font-medium rounded-full border transition-colors',
        variantStyles[variant],
        sizeStyles[size],
        onClick && 'cursor-pointer hover:opacity-80 active:scale-[0.98]',
        className
      )}
      onClick={onClick}
      type={onClick ? 'button' : undefined}
    >
      {dot && (
        <span
          className={classNames(
            'w-1.5 h-1.5 rounded-full flex-shrink-0',
            variant === 'success' && 'bg-emerald-400',
            variant === 'warning' && 'bg-amber-400',
            variant === 'danger' && 'bg-rose-400',
            variant === 'info' && 'bg-blue-400',
            variant === 'neutral' && 'bg-slate-400',
            variant === 'champagne' && 'bg-brand-secondary',
            variant === 'default' && 'bg-brand-outlineVariant',
            pulse && 'animate-ping'
          )}
        />
      )}
      {children}
    </Component>
  );
}

export interface StatusBadgeProps {
  status: 'active' | 'inactive' | 'pending' | 'error' | 'warning' | 'success';
  label: string;
  size?: 'sm' | 'md' | 'lg';
  showDot?: boolean;
  pulse?: boolean;
}

export function StatusBadge({ status, label, size = 'md', showDot = true, pulse = false }: StatusBadgeProps) {
  const config = {
    active: { variant: 'success' as const, pulse: true },
    inactive: { variant: 'neutral' as const, pulse: false },
    pending: { variant: 'warning' as const, pulse: true },
    error: { variant: 'danger' as const, pulse: false },
    warning: { variant: 'warning' as const, pulse: false },
    success: { variant: 'success' as const, pulse: false },
  }[status];

  return (
    <Badge variant={config.variant} size={size} dot={showDot} pulse={config.pulse || pulse}>
      {label}
    </Badge>
  );
}

export interface MetricBadgeProps {
  value: string | number;
  label: string;
  trend?: { value: number; direction: 'up' | 'down' | 'stable' };
  variant?: 'primary' | 'secondary' | 'accent';
  size?: 'sm' | 'md' | 'lg';
}

export function MetricBadge({ value, label, trend, variant = 'primary', size = 'md' }: MetricBadgeProps) {
  const variantColors = {
    primary: 'text-brand-secondary',
    secondary: 'text-brand-onSurfaceVariant',
    accent: 'text-brand-tertiary',
  };

  return (
    <div className="flex flex-col items-start gap-0.5">
      <div className="flex items-baseline gap-1.5">
        <span className={classNames('font-mono font-semibold', variantColors[variant], size === 'sm' && 'text-lg', size === 'md' && 'text-xl', size === 'lg' && 'text-2xl')}>
          {value}
        </span>
        {trend && (
          <span className={classNames('flex items-center gap-0.5 font-mono text-xs font-medium', trend.direction === 'up' && 'text-emerald-300', trend.direction === 'down' && 'text-rose-300', trend.direction === 'stable' && 'text-slate-400')}>
            {trend.direction === 'up' && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>}
            {trend.direction === 'down' && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7m0 0l-7-7m7 7V3" /></svg>}
            {trend.direction === 'stable' && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 12h14" /></svg>}
            <span>{trend.value >= 0 ? '+' : ''}{trend.value.toFixed(1)}%</span>
          </span>
        )}
      </div>
      <span className="text-label-sm text-brand-onSurfaceVariant/60 uppercase tracking-wider">{label}</span>
    </div>
  );
}

// Tabs Component
// Fluxora design system tabs with pill-style indicators

import { useState, ReactNode } from 'react';
import { classNames } from '@/lib/formatters';

export interface TabItem {
  id: string;
  label: string;
  icon?: ReactNode;
  disabled?: boolean;
  badge?: string | number;
}

export interface TabsProps {
  tabs: TabItem[];
  activeTab: string;
  onChange: (tabId: string) => void;
  variant?: 'pills' | 'underline' | 'segmented';
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
  className?: string;
}

const variantStyles = {
  pills: {
    container: 'bg-brand-surfaceContainerLow/50 rounded-lg p-1',
    tab: `
      rounded-md px-3 py-1.5 text-center font-medium transition-all duration-200
      hover:bg-brand-primary/30 hover:text-brand-secondary
      disabled:opacity-50 disabled:cursor-not-allowed
    `,
    active: 'bg-brand-primary text-brand-secondary shadow-sm shadow-brand-primary/30',
    inactive: 'text-brand-onSurfaceVariant',
  },
  underline: {
    container: 'border-b border-white/10',
    tab: `
      px-3 py-2 text-center font-medium transition-colors duration-200
      border-b-2 border-transparent -mb-px
      hover:text-brand-secondary hover:border-brand-secondary/30
      disabled:opacity-50 disabled:cursor-not-allowed
    `,
    active: 'text-brand-secondary border-brand-secondary',
    inactive: 'text-brand-onSurfaceVariant',
  },
  segmented: {
    container: 'bg-brand-surfaceContainerLow/50 rounded-lg p-1',
    tab: `
      rounded-md px-4 py-2 text-center font-medium transition-all duration-200
      hover:bg-brand-primary/30 hover:text-brand-secondary
      disabled:opacity-50 disabled:cursor-not-allowed
    `,
    active: 'bg-brand-primary text-brand-secondary shadow-sm',
    inactive: 'text-brand-onSurfaceVariant',
  },
};

const sizeStyles = {
  sm: 'text-xs',
  md: 'text-sm',
  lg: 'text-base',
};

export function Tabs({
  tabs,
  activeTab,
  onChange,
  variant = 'pills',
  size = 'md',
  fullWidth = false,
  className,
}: TabsProps) {
  const styles = variantStyles[variant];

  return (
    <div
      className={classNames(
        'flex',
        variant === 'underline' ? 'w-full' : 'inline-flex',
        fullWidth && 'w-full',
        className
      )}
      role="tablist"
      aria-label="Tab navigation"
    >
      {variant !== 'underline' && <div className={classNames(styles.container, fullWidth && 'w-full')}>}
        {tabs.map((tab) => (
          <button
            key={tab.id}
            role="tab"
            aria-selected={activeTab === tab.id}
            aria-controls={`${tab.id}-panel`}
            id={`${tab.id}-tab`}
            disabled={tab.disabled}
            onClick={() => !tab.disabled && onChange(tab.id)}
            className={classNames(
              'flex items-center justify-center gap-1.5',
              styles.tab,
              activeTab === tab.id ? styles.active : styles.inactive,
              sizeStyles[size],
              fullWidth && 'flex-1',
              tab.badge && 'relative'
            )}
            type="button"
          >
            {tab.icon && <span className="flex-shrink-0">{tab.icon}</span>}
            <span>{tab.label}</span>
            {tab.badge && (
              <span className="absolute -top-1 -right-1 w-4 h-4 rounded-full bg-rose-500 text-[9px] font-bold flex items-center justify-center">
                {typeof tab.badge === 'number' && tab.badge > 9 ? '9+' : tab.badge}
              </span>
            )}
          </button>
        ))}
      {variant !== 'underline' && </div>}
    </div>
  );
}

export interface TabPanelProps {
  id: string;
  activeTab: string;
  children: ReactNode;
  className?: string;
}

export function TabPanel({ id, activeTab, children, className }: TabPanelProps) {
  if (activeTab !== id) return null;

  return (
    <div
      role="tabpanel"
      id={`${id}-panel`}
      aria-labelledby={`${id}-tab`}
      className={classNames('animation-fade-in-up', className)}
    >
      {children}
    </div>
  );
}

// Tab Pill variant specifically for the dashboard
export interface TabPillProps {
  tabs: Array<{ id: string; label: string; icon?: ReactNode }>;
  activeTab: string;
  onChange: (tabId: string) => void;
  className?: string;
}

export function TabPills({ tabs, activeTab, onChange, className }: TabPillProps) {
  return (
    <div className={classNames('flex items-center gap-2', className)} role="tablist">
      {tabs.map((tab) => (
        <button
          key={tab.id}
          role="tab"
          aria-selected={activeTab === tab.id}
          onClick={() => onChange(tab.id)}
          className={classNames(
            'tab-pill px-2.5 py-1 rounded text-[11px] font-mono transition-all',
            activeTab === tab.id
              ? 'bg-brand-primary/25 text-brand-tertiary border border-brand-primary/50 font-medium shadow-sm'
              : 'text-brand-onSurfaceVariant hover:text-brand-onSurface border-transparent hover:border-white/20'
          )}
          type="button"
        >
          {tab.icon && <span className="flex-shrink-0 mr-1">{tab.icon}</span>}
          {tab.label}
        </button>
      ))}
    </div>
  );
}

