export function CardSkeleton({ className }: { className?: string }) {
  return (
    <div className={classNames('bg-brand-surfaceContainer/90 border border-white/10 rounded-2xl p-6 space-y-4', className)}>
      <div className="flex items-center justify-between">
        <Skeleton variant="text" width="40%" height="1.25rem" />
        <Skeleton variant="circular" width="2rem" height="2rem" />
      </div>
      <Skeleton variant="rectangular" width="60%" height="2.5rem" />
      <div className="space-y-3">
        <Skeleton variant="text" width="100%" height="1rem" />
        <Skeleton variant="text" width="80%" height="1rem" />
        <Skeleton variant="text" width="60%" height="1rem" />
      </div>
      <Skeleton variant="chart" width="100%" height="12rem" />
