// Tooltip Component
// Fluxora design system tooltip with animations

import { useState, useRef, useEffect, ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { classNames } from '@/lib/formatters';

export interface TooltipProps {
  content: ReactNode;
  children: ReactNode;
  position?: 'top' | 'bottom' | 'left' | 'right';
  offset?: number;
  delay?: number;
  className?: string;
}

export function Tooltip({ content, children, position = 'top', offset = 8, delay = 150, className }: TooltipProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [tooltipRect, setTooltipRect] = useState<DOMRect | null>(null);
  const triggerRef = useRef<HTMLElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const timeoutRef = useRef<NodeJS.Timeout>();

  const showTooltip = () => {
    timeoutRef.current = setTimeout(() => {
      setIsOpen(true);
      if (triggerRef.current) {
        setTooltipRect(triggerRef.current.getBoundingClientRect());
      }
    }, delay);
  };

  const hideTooltip = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setIsOpen(false);
  };

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  if (!isOpen || !tooltipRef.current || !triggerRef.current) return <>{children}</>;

  const triggerRect = triggerRef.current.getBoundingClientRect();
  const tooltipWidth = tooltipRef.current.offsetWidth;
  const tooltipHeight = tooltipRef.current.offsetHeight;

  let top = 0;
  let left = 0;
  let transform = '';
  let arrowPosition = '';

  switch (position) {
    case 'top':
      top = triggerRect.top - tooltipHeight - offset;
      left = triggerRect.left + triggerRect.width / 2 - tooltipWidth / 2;
      transform = 'translateX(-50%)';
      arrowPosition = 'bottom-0 left-1/2 -translate-x-1/2 translate-y-full';
      break;
    case 'bottom':
      top = triggerRect.bottom + offset;
      left = triggerRect.left + triggerRect.width / 2 - tooltipWidth / 2;
      transform = 'translateX(-50%)';
      arrowPosition = 'top-0 left-1/2 -translate-x-1/2 -translate-y-full';
      break;
    case 'left':
      top = triggerRect.top + triggerRect.height / 2 - tooltipHeight / 2;
      left = triggerRect.left - tooltipWidth - offset;
      transform = 'translateY(-50%)';
      arrowPosition = 'right-0 top-1/2 -translate-y-1/2 translate-x-full';
      break;
    case 'right':
      top = triggerRect.top + triggerRect.height / 2 - tooltipHeight / 2;
      left = triggerRect.right + offset;
      transform = 'translateY(-50%)';
      arrowPosition = 'left-0 top-1/2 -translate-y-1/2 -translate-x-full';
      break;
  }

  // Keep tooltip in viewport
  const viewportPadding = 16;
  if (left < viewportPadding) left = viewportPadding;
  if (left + tooltipWidth > window.innerWidth - viewportPadding) {
    left = window.innerWidth - tooltipWidth - viewportPadding;
  }
  if (top < viewportPadding) top = viewportPadding;
  if (top + tooltipHeight > window.innerHeight - viewportPadding) {
    top = window.innerHeight - tooltipHeight - viewportPadding;
  }

  const tooltipElement = (
    <div
      ref={tooltipRef}
      className={classNames(
        'fixed z-50 px-3 py-2 rounded-lg bg-brand-surfaceContainerHighest/95 border border-brand-secondary/20',
        'text-body-sm text-brand-onSurface shadow-xl shadow-black/50 backdrop-blur-xl',
        'animation-fade-in-up whitespace-nowrap max-w-[300px]',
        className
      )}
      style={{ top, left, transform }}
      role="tooltip"
      aria-live="polite"
    >
      {content}
      <div
        className={classNames(
          'absolute w-0 h-0 border-4 border-transparent',
          position === 'top' && 'border-t-brand-surfaceContainerHighest bottom-0 left-1/2 -translate-x-1/2 translate-y-full',
          position === 'bottom' && 'border-b-brand-surfaceContainerHighest top-0 left-1/2 -translate-x-1/2 -translate-y-full',
          position === 'left' && 'border-l-brand-surfaceContainerHighest right-0 top-1/2 -translate-y-1/2 translate-x-full',
          position === 'right' && 'border-r-brand-surfaceContainerHighest left-0 top-1/2 -translate-y-1/2 -translate-x-full',
        )}
      />
    </div>
  );

  return (
    <>
      <span
        ref={triggerRef}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
        onFocus={showTooltip}
        onBlur={hideTooltip}
        tabIndex={0}
      >
        {children}
      </span>
      {createPortal(tooltipElement, document.body)}
    </>
  );
}

