// Dropdown Component
// Fluxora design system dropdown menu

import { useState, useRef, useEffect, ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { classNames } from '@/lib/formatters';

export interface DropdownItem {
  label: string;
  value: string;
  icon?: ReactNode;
  disabled?: boolean;
  danger?: boolean;
  divider?: boolean;
  subtitle?: string;
}

export interface DropdownProps {
  trigger: ReactNode;
  items: DropdownItem[];
  onSelect: (value: string) => void;
  position?: 'bottom' | 'top' | 'left' | 'right';
  align?: 'start' | 'center' | 'end';
  width?: number | 'trigger';
  closeOnSelect?: boolean;
  className?: string;
}

export function Dropdown({
  trigger,
  items,
  onSelect,
  position = 'bottom',
  align = 'start',
  width = 'trigger',
  closeOnSelect = true,
  className,
}: DropdownProps) {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const toggle = () => setIsOpen(!isOpen);
  const close = () => setIsOpen(false);

  const handleSelect = (value: string) => {
    onSelect(value);
    if (closeOnSelect) close();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') close();
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      toggle();
    }
  };

  // Close on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (triggerRef.current && !triggerRef.current.contains(event.target as Node) &&
          dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        close();
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  // Position calculation
  const getPositionStyles = () => {
    if (!triggerRef.current) return {};

    const rect = triggerRef.current.getBoundingClientRect();
    const dropdownWidth = width === 'trigger' ? rect.width : typeof width === 'number' ? width : 240;

    let top = 0;
    let left = 0;
    let transform = '';

    switch (position) {
      case 'bottom':
        top = rect.bottom + 4;
        if (align === 'start') left = rect.left;
        else if (align === 'center') left = rect.left + rect.width / 2 - dropdownWidth / 2;
        else left = rect.right - dropdownWidth;
        break;
      case 'top':
        top = rect.top - 4;
        if (align === 'start') left = rect.left;
        else if (align === 'center') left = rect.left + rect.width / 2 - dropdownWidth / 2;
        else left = rect.right - dropdownWidth;
        break;
    }

    // Keep in viewport
    const viewportPadding = 16;
    if (left < viewportPadding) left = viewportPadding;
    if (left + dropdownWidth > window.innerWidth - viewportPadding) {
      left = window.innerWidth - dropdownWidth - viewportPadding;
    }

    return { top, left, width: dropdownWidth, transform };
  };

  const positionStyles = getPositionStyles();

  const dropdownContent = isOpen ? (
    <div
      ref={dropdownRef}
      className={classNames(
        'fixed z-50 rounded-xl bg-brand-surfaceContainerHighest/95 border border-brand-secondary/20',
        'shadow-2xl shadow-black/60 backdrop-blur-xl overflow-hidden',
        'animation-fade-in-up ring-1 ring-black/20',
        className
      )}
      style={positionStyles}
      role="menu"
      aria-orientation="vertical"
    >
      {items.map((item, index) => (
        item.divider ? (
          <div key={`divider-${index}`} className="h-px bg-white/10 mx-2 my-1" role="separator" />
        ) : (
          <button
            key={item.value}
            onClick={() => !item.disabled && handleSelect(item.value)}
            disabled={item.disabled}
            role="menuitem"
            tabIndex={-1}
            className={classNames(
              'w-full px-4 py-2.5 flex items-center gap-3 text-left',
              'transition-colors duration-150',
              'hover:bg-brand-primary/30 hover:text-brand-secondary',
              'focus:outline-none focus:bg-brand-primary/30 focus:text-brand-secondary',
              item.disabled && 'opacity-50 cursor-not-allowed',
              item.danger && 'text-rose-400 hover:bg-rose-950/30 hover:text-rose-300',
              'first:rounded-t-xl last:rounded-b-xl'
            )}
            type="button"
          >
            {item.icon && <span className="flex-shrink-0 w-5 h-5">{item.icon}</span>}
            <div className="flex-1 min-w-0">
              <span className="block text-body-sm font-medium truncate">{item.label}</span>
              {item.subtitle && <span className="block text-label-sm text-brand-onSurfaceVariant/60 truncate">{item.subtitle}</span>}
            </div>
          </button>
        )
      ))}
    </div>
  ) : null;

  return (
    <>
      <button
        ref={triggerRef}
        onClick={toggle}
        onKeyDown={handleKeyDown}
        aria-haspopup="menu"
        aria-expanded={isOpen}
        className="flex items-center gap-2"
        type="button"
      >
        {trigger}
      </button>
      {createPortal(dropdownContent, document.body)}
    </>
  );
}

