// Energy Chart Component
// Recharts-based time series chart for energy data

import {
  LineChart,
  Line,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  ReferenceLine,
} from 'recharts';
import { ReactNode, useMemo } from 'react';
import { formatTime, formatEnergy } from '@/lib/formatters';
import type { ChartDataPoint } from '@/types';
import { CHART_COLORS, CHART_CONFIG } from '@/lib/constants';

interface EnergyChartProps {
  data: ChartDataPoint[];
  forecastData?: ChartDataPoint[];
  anomalyData?: ChartDataPoint[];
  height?: number;
  showGrid?: boolean;
  showLegend?: boolean;
  showTooltip?: boolean;
  yAxisLabel?: string;
  xAxisLabel?: string;
  animate?: boolean;
  className?: string;
  onPointClick?: (point: ChartDataPoint, index: number) => void;
}

export function EnergyChart({
  data,
  forecastData = [],
  anomalyData = [],
  height = 300,
  showGrid = true,
  showLegend = true,
  showTooltip = true,
  yAxisLabel = 'Energy (kWh)',
  xAxisLabel = 'Time',
  animate = true,
  className,
  onPointClick,
}: EnergyChartProps) {
  const chartData = useMemo(() => {
    const combined = [...data];
    if (forecastData.length > 0) {
      combined.push(...forecastData);
    }
    return combined.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
  }, [data, forecastData]);

  const actualData = data.filter(d => !d.isForecast);
  const forecastOnly = forecastData.filter(d => d.isForecast);

  const CustomTooltip = ({ active, payload, label }: { active?: boolean; payload?: Array<{ value: number; name: string; color: string; payload: ChartDataPoint }>; label?: string }) => {
    if (!active || !payload || !label) return null;

    const point = payload[0]?.payload;
    const isForecastPoint = point?.isForecast;
    const isAnomalyPoint = point?.isAnomaly;

    return (
      <div className="bg-brand-surfaceContainerHighest/95 border border-brand-secondary/20 rounded-xl p-3 shadow-2xl shadow-black/50 backdrop-blur-xl min-w-[200px]">
        <div className="flex items-center gap-2 mb-2">
          <span className="text-label-md text-brand-secondary font-mono">{formatTime(label)}</span>
          {isForecastPoint && <span className="text-[10px] px-1.5 py-0.5 rounded bg-brand-tertiary/20 text-brand-tertiary font-mono">Forecast</span>}
          {isAnomalyPoint && <span className="text-[10px] px-1.5 py-0.5 rounded bg-rose-500/20 text-rose-400 font-mono">Anomaly</span>}
        </div>
        {payload.map((entry, index) => (
          <div key={index} className="flex items-center justify-between gap-4 text-body-sm">
            <span className="text-brand-onSurfaceVariant">{entry.name}</span>
            <span className="font-mono font-semibold text-brand-onSurface">{formatEnergy(entry.value)}</span>
          </div>
        ))}
        {point?.lowerBound !== undefined && point?.upperBound !== undefined && (
          <div className="mt-2 pt-2 border-t border-white/10 text-label-sm text-brand-onSurfaceVariant">
            Confidence: {formatEnergy(point.lowerBound)} - {formatEnergy(point.upperBound)}
          </div>
        )}
      </div>
    );
  };

  const yAxisDomain = useMemo(() => {
    const values = [...data, ...forecastData].map(d => d.value).filter(v => v !== null && v !== undefined);
    if (values.length === 0) return [0, 100] as [number, number];
    const min = Math.min(...values);
    const max = Math.max(...values);
    const padding = (max - min) * 0.1 || 10;
    return [Math.max(0, min - padding), max + padding] as [number, number];
  }, [data, forecastData]);

  return (
    <div className={classNames('w-full', className)} style={{ height }}>
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={chartData} margin={CHART_CONFIG.margin}>
          <defs>
            <linearGradient id="actualGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={CHART_COLORS.primary} stopOpacity={0.3} />
              <stop offset="100%" stopColor={CHART_COLORS.primary} stopOpacity={0} />
            </linearGradient>
            <linearGradient id="forecastGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={CHART_COLORS.secondary} stopOpacity={0.2} />
              <stop offset="100%" stopColor={CHART_COLORS.secondary} stopOpacity={0} />
            </linearGradient>
          </defs>

          {showGrid && (
            <CartesianGrid
              stroke={CHART_COLORS.grid}
              strokeDasharray="4 4"
              vertical={false}
              horizontal={true}
            />
          )}

          <XAxis
            dataKey="timestamp"
            tickFormatter={formatTime}
            tick={{ fill: CHART_COLORS.textMuted, fontSize: 11, fontFamily: 'var(--font-jetbrains-mono)' }}
            axisLine={{ stroke: CHART_COLORS.grid }}
            tickLine={{ stroke: CHART_COLORS.grid }}
            label={{ value: xAxisLabel, position: 'insideBottom', offset: -10, fill: CHART_COLORS.textMuted, fontSize: 11 }}
            interval="preserveStartEnd"
          />

          <YAxis
            domain={yAxisDomain}
            tick={{ fill: CHART_COLORS.textMuted, fontSize: 11, fontFamily: 'var(--font-jetbrains-mono)' }}
            axisLine={{ stroke: CHART_COLORS.grid }}
            tickLine={{ stroke: CHART_COLORS.grid }}
            label={{ value: yAxisLabel, angle: -90, position: 'insideLeft', offset: 20, fill: CHART_COLORS.textMuted, fontSize: 11 }}
            width={60}
          />

          {showTooltip && (
            <Tooltip
              content={<CustomTooltip />}
              wrapperStyle={{
                backgroundColor: 'transparent',
                border: 'none',
                boxShadow: 'none',
                padding: 0,
              }}
            />
          )}

          {showLegend && (
            <Legend
              wrapperStyle={{ paddingTop: 20 }}
              formatter={(value) => value}
            />
          )}

          {/* Actual Data Area */}
          {actualData.length > 0 && (
            <Area
              type={CHART_CONFIG.curveType}
              dataKey="value"
              data={actualData}
              name="Actual"
              stroke={CHART_COLORS.primary}
              strokeWidth={CHART_CONFIG.strokeWidth}
              fill="url(#actualGradient)"
              fillOpacity={0.6}
              dot={false}
              activeDot={{ r: CHART_CONFIG.activeDotRadius, strokeWidth: 2 }}
              isAnimationActive={animate}
              animationDuration={CHART_CONFIG.animationDuration}
              onClick={(_, payload) => onPointClick?.(payload.payload, payload.index)}
            />
          )}

          {/* Actual Data Line */}
          {actualData.length > 0 && (
            <Line
              type={CHART_CONFIG.curveType}
              dataKey="value"
              data={actualData}
              name="Actual"
              stroke={CHART_COLORS.primary}
              strokeWidth={CHART_CONFIG.strokeWidth}
              dot={false}
              activeDot={{ r: CHART_CONFIG.activeDotRadius, strokeWidth: 2, fill: CHART_COLORS.primary }}
              isAnimationActive={animate}
              animationDuration={CHART_CONFIG.animationDuration}
              legendType="line"
              onClick={(_, payload) => onPointClick?.(payload.payload, payload.index)}
            />
          )}

          {/* Forecast Data Area */}
          {forecastOnly.length > 0 && (
            <Area
              type={CHART_CONFIG.curveType}
              dataKey="value"
              data={forecastOnly}
              name="Forecast"
              stroke={CHART_COLORS.secondary}
              strokeWidth={CHART_CONFIG.strokeWidth}
              strokeDasharray="6 4"
              fill="url(#forecastGradient)"
              fillOpacity={0.4}
              dot={false}
              activeDot={{ r: CHART_CONFIG.activeDotRadius, strokeWidth: 2, fill: CHART_COLORS.secondary }}
              isAnimationActive={animate}
              animationDuration={CHART_CONFIG.animationDuration}
              legendType="dash"
              onClick={(_, payload) => onPointClick?.(payload.payload, payload.index)}
            />
          )}

          {/* Anomaly Points */}
          {anomalyData.length > 0 && anomalyData.map((anomaly, index) => (
            <ReferenceLine
              key={`anomaly-${index}`}
              x={anomaly.timestamp}
              stroke={CHART_COLORS.danger}
              strokeWidth={1.5}
              strokeDasharray="4 4"
              label={{
                value: '⚠',
                position: 'top',
                fill: CHART_COLORS.danger,
                fontSize: 14,
                background: { fill: 'rgba(13, 34, 28, 0.9)', padding: 2, borderRadius: 4 },
              }}
            />
          ))}

          {/* Forecast Start Line */}
          {forecastOnly.length > 0 && actualData.length > 0 && (
            <ReferenceLine
              x={forecastOnly[0].timestamp}
              stroke={CHART_COLORS.secondary}
              strokeWidth={1}
              strokeDasharray="8 4"
              label={{
                value: 'Forecast begins',
                position: 'top',
                fill: CHART_COLORS.secondary,
                fontSize: 10,
                fontFamily: 'var(--font-jetbrains-mono)',
                background: { fill: 'rgba(13, 34, 28, 0.9)', padding: 4, borderRadius: 4 },
              }}
            />
          )}
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}

// Simplified Mini Chart for cards
export interface MiniChartProps {
  data: ChartDataPoint[];
  color?: string;
  height?: number;
  showArea?: boolean;
  className?: string;
}

export function MiniChart({ data, color = CHART_COLORS.primary, height = 60, showArea = true, className }: MiniChartProps) {
  if (data.length === 0) return <div className={classNames('w-full h-full', className)} />;

  const maxValue = Math.max(...data.map(d => d.value));
  const minValue = Math.min(...data.map(d => d.value));

  return (
    <div className={classNames('w-full', className)} style={{ height }}>
      <svg width="100%" height="100%" viewBox={`0 0 ${data.length * 4} ${height}`} preserveAspectRatio="none">
        {showArea && (
          <path
            d={data.map((d, i) => {
              const x = i * 4;
              const y = height - ((d.value - minValue) / (maxValue - minValue || 1)) * (height - 10);
              return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
            }).join(' ')} L${(data.length - 1) * 4} ${height} L0 ${height} Z
            fill={color}
            fillOpacity="0.15"
          />
        )}
        <path
          d={data.map((d, i) => {
            const x = i * 4;
            const y = height - ((d.value - minValue) / (maxValue - minValue || 1)) * (height - 10);
            return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
          }).join(' ')}
          stroke={color}
          strokeWidth={1.5}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </div>
  );
}

// Anomaly List Component
// Display and filter anomaly detection results

import { useState, useMemo } from 'react';
import { formatRelativeTime, formatEnergy, getSeverityColor, classNames } from '@/lib/formatters';
import type { Anomaly } from '@/types';
import { Card } from '@/components/shared/Card';
import { Badge, StatusBadge } from '@/components/shared/Badge';
import { Button } from '@/components/shared/Button';
import { Dropdown, DropdownItem } from '@/components/shared/Dropdown';
import { EmptyState } from '@/components/shared/States';
import { 
  AlertTriangle, 
  AlertCircle, 
  CheckCircle, 
  XCircle, 
  Search, 
  Filter, 
  ChevronDown,
  Clock,
  Zap
} from 'lucide-react';

interface AnomalyListProps {
  anomalies: Anomaly[];
  onStatusChange?: (anomalyId: string, status: Anomaly['status']) => void;
  onViewDetails?: (anomaly: Anomaly) => void;
  loading?: boolean;
  emptyMessage?: string;
  showFilters?: boolean;
  className?: string;
}

const severityIcons = {
  low: <Zap className="w-4 h-4" />,
  medium: <AlertTriangle className="w-4 h-4" />,
  high: <AlertTriangle className="w-4 h-4" />,
  critical: <AlertCircle className="w-4 h-4" />,
};

const statusConfig = {
  new: { icon: <Clock className="w-3.5 h-3.5" />, label: 'New' },
  investigating: { icon: <Search className="w-3.5 h-3.5" />, label: 'Investigating' },
  resolved: { icon: <CheckCircle className="w-3.5 h-3.5" />, label: 'Resolved' },
  dismissed: { icon: <XCircle className="w-3.5 h-3.5" />, label: 'Dismissed' },
};

export function AnomalyList({
  anomalies,
  onStatusChange,
  onViewDetails,
  loading = false,
  emptyMessage = 'No anomalies detected for the selected period.',
  showFilters = true,
  className,
}: AnomalyListProps) {
  const [searchQuery, setSearchQuery] = useState('');
  const [severityFilter, setSeverityFilter] = useState<Anomaly['severity'] | 'all'>('all');
  const [statusFilter, setStatusFilter] = useState<Anomaly['status'] | 'all'>('all');
  const [sortBy, setSortBy] = useState<'timestamp' | 'score' | 'severity'>('timestamp');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');

  const filteredAnomalies = useMemo(() => {
    let result = anomalies;

    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      result = result.filter(a => 
        a.id.toLowerCase().includes(query) ||
        a.label.toLowerCase().includes(query) ||
        a.meterId?.toLowerCase().includes(query) ||
        a.buildingId?.toLowerCase().includes(query)
      );
    }

    if (severityFilter !== 'all') {
      result = result.filter(a => a.severity === severityFilter);
    }

    if (statusFilter !== 'all') {
      result = result.filter(a => a.status === statusFilter);
    }

    result.sort((a, b) => {
      let comparison = 0;
      switch (sortBy) {
        case 'timestamp':
          comparison = new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime();
          break;
        case 'score':
          comparison = a.score - b.score;
          break;
        case 'severity': {
          const severityOrder = { critical: 4, high: 3, medium: 2, low: 1 };
          comparison = severityOrder[a.severity] - severityOrder[b.severity];
          break;
        }
      }
      return sortOrder === 'asc' ? comparison : -comparison;
    });

    return result;
  }, [anomalies, searchQuery, severityFilter, statusFilter, sortBy, sortOrder]);

  if (loading) {
    return (
      <Card className={className} padding="none">
        <div className="p-6 space-y-4">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-lg bg-brand-surfaceContainerHigh animate-pulse" />
              <div className="flex-1 space-y-2">
                <div className="h-4 w-1/3 bg-brand-surfaceContainerHigh animate-pulse rounded" />
                <div className="h-3 w-1/4 bg-brand-surfaceContainerHigh animate-pulse rounded" />
              </div>
              <div className="w-24 h-6 bg-brand-surfaceContainerHigh animate-pulse rounded" />
            </div>
          ))}
        </div>
      </Card>
    );
  }

  if (filteredAnomalies.length === 0) {
    return (
      <Card className={className} padding="none">
        <EmptyState
          title="No anomalies found"
          message={emptyMessage}
          illustration="alert"
          variant="card"
        />
      </Card>
    );
  }

  const severityItems: DropdownItem[] = [
    { label: 'All Severities', value: 'all' },
    { label: 'Critical', value: 'critical', icon: <AlertCircle className="w-4 h-4 text-rose-400" /> },
    { label: 'High', value: 'high', icon: <AlertTriangle className="w-4 h-4 text-orange-400" /> },
    { label: 'Medium', value: 'medium', icon: <AlertTriangle className="w-4 h-4 text-amber-400" /> },
    { label: 'Low', value: 'low', icon: <Zap className="w-4 h-4 text-emerald-400" /> },
  ];

  const statusItems: DropdownItem[] = [
    { label: 'All Statuses', value: 'all' },
    { label: 'New', value: 'new', icon: <Clock className="w-4 h-4 text-brand-tertiary" /> },
    { label: 'Investigating', value: 'investigating', icon: <Search className="w-4 h-4 text-amber-400" /> },
    { label: 'Resolved', value: 'resolved', icon: <CheckCircle className="w-4 h-4 text-emerald-400" /> },
    { label: 'Dismissed', value: 'dismissed', icon: <XCircle className="w-4 h-4 text-slate-400" /> },
  ];

  const sortItems: DropdownItem[] = [
    { label: 'Newest First', value: 'timestamp-desc' },
    { label: 'Oldest First', value: 'timestamp-asc' },
    { label: 'Highest Score', value: 'score-desc' },
    { label: 'Lowest Score', value: 'score-asc' },
    { label: 'Most Severe', value: 'severity-desc' },
  ];

  return (
    <Card variant="elevated" className={className}>
      {showFilters && (
        <div className="mb-6 flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
          <div className="relative w-full sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
            <input
              type="text"
              placeholder="Search anomalies..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-brand-surfaceContainerLow/80 border border-brand-outlineVariant/50 rounded-lg text-brand-onSurface placeholder:text-brand-onSurfaceVariant/50 focus:outline-none focus:ring-2 focus:ring-brand-secondary/50 focus:border-brand-secondary"
            />
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            <Dropdown
              trigger={
                <Button variant="outline" size="sm" icon={<Filter className="w-4 h-4" />} iconPosition="left">
                  Severity: {severityFilter === 'all' ? 'All' : severityFilter.charAt(0).toUpperCase() + severityFilter.slice(1)}
                  <ChevronDown className="w-4 h-4 ml-1" />
                </Button>
              }
              items={severityItems}
              onSelect={setSeverityFilter}
            />
            <Dropdown
              trigger={
                <Button variant="outline" size="sm" icon={<Filter className="w-4 h-4" />} iconPosition="left">
                  Status: {statusFilter === 'all' ? 'All' : statusFilter.charAt(0).toUpperCase() + statusFilter.slice(1)}
                  <ChevronDown className="w-4 h-4 ml-1" />
                </Button>
              }
              items={statusItems}
              onSelect={setStatusFilter}
            />
            <Dropdown
              trigger={
                <Button variant="outline" size="sm" icon={<ChevronDown className="w-4 h-4" />} iconPosition="right">
                  Sort: {sortBy} ({sortOrder})
                  <ChevronDown className="w-4 h-4 ml-1" />
                </Button>
              }
              items={sortItems}
              onSelect={value => {
                const [field, order] = value.split('-');
                setSortBy(field as typeof sortBy);
                setSortOrder(order as typeof sortOrder);
              }}
            />
          </div>
        </div>
      )}

      <div className="space-y-3">
        {filteredAnomalies.map((anomaly, index) => (
          <AnomalyItem
            key={anomaly.id}
            anomaly={anomaly}
            index={index}
            onStatusChange={onStatusChange}
            onViewDetails={onViewDetails}
          />
        ))}
      </div>

      {anomalies.length > filteredAnomalies.length && (
        <p className="mt-4 text-center text-label-md text-brand-onSurfaceVariant/60">
          Showing {filteredAnomalies.length} of {anomalies.length} anomalies
        </p>
      )}
    </Card>
  );
}

interface AnomalyItemProps {
  anomaly: Anomaly;
  index: number;
  onStatusChange?: (anomalyId: string, status: Anomaly['status']) => void;
  onViewDetails?: (anomaly: Anomaly) => void;
}

function AnomalyItem({ anomaly, onStatusChange, onViewDetails }: AnomalyItemProps) {
  const statusItem = statusConfig[anomaly.status];
  const severityStyle = getSeverityColor(anomaly.severity);

  const statusItems: DropdownItem[] = [
    { label: 'Mark as New', value: 'new', icon: <Clock className="w-4 h-4" /> },
    { label: 'Mark Investigating', value: 'investigating', icon: <Search className="w-4 h-4" /> },
    { label: 'Mark Resolved', value: 'resolved', icon: <CheckCircle className="w-4 h-4" /> },
    { label: 'Dismiss', value: 'dismissed', icon: <XCircle className="w-4 h-4" /> },
  ];

  return (
    <div
      className={classNames(
        'group p-4 rounded-xl bg-brand-surfaceContainer/50 border transition-all duration-200',
        'hover:border-brand-secondary/30 hover:bg-brand-surfaceContainer/80',
        anomaly.severity === 'critical' && 'border-rose-500/30 bg-rose-950/10',
        anomaly.severity === 'high' && 'border-orange-500/30 bg-orange-950/10',
        anomaly.status === 'resolved' && 'opacity-60',
        anomaly.status === 'dismissed' && 'opacity-40'
      )}
    >
      <div className="flex items-start gap-4">
        <div className={classNames('flex-shrink-0 w-10 h-10 rounded-lg flex items-center justify-center', severityStyle.split(' ')[1] || '')}>
          {severityIcons[anomaly.severity]}
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-4">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap mb-1">
                <span className="font-mono text-label-md text-brand-secondary">{anomaly.id.slice(0, 8)}...</span>
                <StatusBadge status={anomaly.status} size="sm" />
                <Badge variant="champagne" size="sm">{anomaly.label}</Badge>
              </div>
              <p className="text-body-md text-brand-onSurface truncate">{anomaly.recommendation || 'No recommendation provided'}</p>
              <div className="mt-2 flex flex-wrap items-center gap-4 text-label-sm text-brand-onSurfaceVariant">
                <span className="flex items-center gap-1.5">
                  <Clock className="w-3.5 h-3.5" />
                  {formatRelativeTime(anomaly.timestamp)}
                </span>
                {anomaly.meterId && (
                  <span className="flex items-center gap-1.5 font-mono">
                    <Zap className="w-3.5 h-3.5" />
                    {anomaly.meterId}
                  </span>
                )}
                <span className="flex items-center gap-1.5 font-mono">
                  Score: <span className="font-semibold text-brand-onSurface">{anomaly.score.toFixed(3)}</span>
                </span>
                {anomaly.value !== undefined && (
                  <span className="flex items-center gap-1.5 font-mono">
                    Value: <span className="font-semibold text-brand-onSurface">{formatEnergy(anomaly.value)}</span>
                  </span>
                )}
              </div>
            </div>

            <div className="flex items-center gap-2 flex-shrink-0">
              <Dropdown
                trigger={
                  <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                    <ChevronDown className="w-4 h-4" />
                  </Button>
                }
                items={statusItems}
                onSelect={value => onStatusChange?.(anomaly.id, value as Anomaly['status'])}
                align="end"
              />
              {onViewDetails && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-8 w-8 p-0"
                  onClick={() => onViewDetails(anomaly)}
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                  </svg>
                </Button>
              )}
            </div>
          </div>

          {anomaly.contextualData && (
            <div className="mt-3 pt-3 border-t border-white/10 grid grid-cols-2 sm:grid-cols-4 gap-4 text-label-sm">
              {anomaly.contextualData.temperature !== undefined && (
                <div className="flex items-center gap-1.5 text-brand-onSurfaceVariant">
                  <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                  <span>{anomaly.contextualData.temperature}°C</span>
                </div>
              )}
              {anomaly.contextualData.occupancy !== undefined && (
                <div className="flex items-center gap-1.5 text-brand-onSurfaceVariant">
                  <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                  <span>{anomaly.contextualData.occupancy}%</span>
                </div>
              )}
              {anomaly.contextualData.weather && (
                <div className="flex items-center gap-1.5 text-brand-onSurfaceVariant">
                  <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 10-9.78 2.096A4.001 4.001 0 003 15z" /></svg>
                  <span>{anomaly.contextualData.weather}</span>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// Carbon Summary Component
// Display carbon emissions analytics

import { useMemo } from 'react';
import { formatNumber, formatPercent, formatCurrency, formatEnergy, classNames } from '@/lib/formatters';
import type { CarbonSummary } from '@/types';
import { Card, CardHeader, CardContent, CardFooter } from '@/components/shared/Card';
import { Badge } from '@/components/shared/Badge';
import { Button } from '@/components/shared/Button';
import { EmptyState } from '@/components/shared/States';
import { EnergyChart } from './EnergyChart';
import { 
  Leaf, 
  TrendingUp, 
  TrendingDown, 
  Minus,
  AlertTriangle,
  Info,
  ExternalLink,
  Download
} from 'lucide-react';

interface CarbonSummaryProps {
  summary: CarbonSummary | null;
  loading?: boolean;
  error?: Error | null;
  onConfigureFactor?: () => void;
  onExport?: () => void;
  className?: string;
}

export function CarbonSummary({
  summary,
  loading = false,
  error,
  onConfigureFactor,
  onExport,
  className,
}: CarbonSummaryProps) {
  if (loading) {
    return (
      <Card variant="elevated" className={className} padding="lg">
        <CardHeader title="Carbon Emissions" description="Estimated emissions for the selected period" />
        <CardContent>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="space-y-2">
                <div className="h-10 w-3/4 bg-brand-surfaceContainerHigh animate-pulse rounded" />
                <div className="h-4 w-1/2 bg-brand-surfaceContainerHigh animate-pulse rounded" />
              </div>
            ))}
          </div>
          <div className="h-64 bg-brand-surfaceContainerHigh animate-pulse rounded-xl" />
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card variant="elevated" className={className} padding="lg">
        <CardHeader title="Carbon Emissions" />
        <CardContent>
          <EmptyState
            title="Unable to load carbon data"
            message={error.message}
            illustration="alert"
            action={onConfigureFactor && (
              <Button onClick={onConfigureFactor} icon={<AlertTriangle className="w-4 h-4" />}>
                Configure Emission Factor
              </Button>
            )}
            variant="card"
          />
        </CardContent>
      </Card>
    );
  }

  if (!summary || !summary.isFactorConfigured) {
    return (
      <Card variant="elevated" className={className} padding="lg">
        <CardHeader 
          title="Carbon Emissions" 
          description="Configure an emission factor to view carbon analytics"
          badge={<Badge variant="warning" dot><AlertTriangle className="w-3 h-3" /> Factor Required</Badge>}
        />
        <CardContent>
          <EmptyState
            title="Emission factor not configured"
            message={summary?.missingFactorMessage || 'No emission factor configured. Please configure an emission factor in settings to view carbon analytics.'}
            illustration="config"
            action={onConfigureFactor && (
              <Button onClick={onConfigureFactor} icon={<AlertTriangle className="w-4 h-4" />}>
                Configure Emission Factor
              </Button>
            )}
            variant="card"
          />
        </CardContent>
      </Card>
    );
  }

  const trendDirection = summary.trend?.changePercent 
    ? summary.trend.changePercent > 0 ? 'up' : summary.trend.changePercent < 0 ? 'down' : 'stable'
    : 'stable';

  const trendIcon = trendDirection === 'up' ? <TrendingUp className="w-4 h-4 text-rose-400" /> 
    : trendDirection === 'down' ? <TrendingDown className="w-4 h-4 text-emerald-400" /> 
    : <Minus className="w-4 h-4 text-slate-400" />;

  const chartData = useMemo(() => {
    // In a real implementation, this would come from the API
    // For now, we'll create a simple trend based on the summary
    return [];
  }, [summary]);

  return (
    <Card variant="elevated" className={className}>
      <CardHeader
        title="Carbon Emissions"
        description={`Estimated emissions for ${new Date(summary.period.start).toLocaleDateString()} - ${new Date(summary.period.end).toLocaleDateString()}`}
        badge={
          <Badge variant="champagne" dot pulse>
            <Info className="w-3 h-3" /> Estimated
          </Badge>
        }
        action={
          <div className="flex items-center gap-2">
            {onExport && (
              <Button variant="ghost" size="sm" onClick={onExport} icon={<Download className="w-4 h-4" />}>
                Export
              </Button>
            )}
            {summary.emissionFactor.sourceUrl && (
              <a
                href={summary.emissionFactor.sourceUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="p-2 rounded-lg hover:bg-white/[0.05] text-brand-onSurfaceVariant transition-colors"
                aria-label="View emission factor source"
              >
                <ExternalLink className="w-4 h-4" />
              </a>
            )}
          </div>
        }
      />

      <CardContent>
        {/* KPI Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <KPICard
            label="Total Emissions"
            value={formatNumber(summary.totalEmissions, 2)}
            unit="tCO₂e"
            icon={<Leaf className="w-5 h-5 text-emerald-400" />}
            trend={{
              value: Math.abs(summary.trend?.changePercent || 0),
              direction: trendDirection,
              period: 'vs previous period'
            }}
            status={trendDirection === 'down' ? 'good' : trendDirection === 'up' ? 'warning' : 'unknown'}
          />
          <KPICard
            label="Emission Factor"
            value={summary.emissionFactor.value.toFixed(3)}
            unit="kgCO₂e/kWh"
            icon={<Info className="w-5 h-5 text-brand-tertiary" />}
            variant="secondary"
          />
          <KPICard
            label="Scope 2 Emissions"
            value={formatNumber(summary.breakdown?.scope2 || 0, 2)}
            unit="tCO₂e"
            icon={<Leaf className="w-5 h-5 text-brand-secondary" />}
            variant="secondary"
          />
          <KPICard
            label="Data Points"
            value={summary.dataPoints.toLocaleString()}
            unit="readings"
            icon={<Info className="w-5 h-5 text-slate-400" />}
            variant="neutral"
          />
        </div>

        {/* Emission Factor Details */}
        <div className="mb-6 p-4 rounded-xl bg-brand-surfaceContainerLow/50 border border-brand-outlineVariant/30">
          <div className="flex items-start justify-between gap-4">
            <div className="flex-1">
              <h4 className="text-headline-sm text-brand-onSurface mb-2 flex items-center gap-2">
                <Info className="w-5 h-5 text-brand-tertiary" />
                Emission Factor Details
              </h4>
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-body-sm">
                <div>
                  <span className="text-brand-onSurfaceVariant">Source:</span>
                  <span className="ml-2 text-brand-onSurface font-medium">{summary.emissionFactor.source}</span>
                </div>
                <div>
                  <span className="text-brand-onSurfaceVariant">Region:</span>
                  <span className="ml-2 text-brand-onSurface font-medium">{summary.emissionFactor.region}</span>
                </div>
                <div>
                  <span className="text-brand-onSurfaceVariant">Valid:</span>
                  <span className="ml-2 text-brand-onSurface font-medium">
                    {new Date(summary.emissionFactor.validFrom).toLocaleDateString()}
                    {summary.emissionFactor.validTo && ` - ${new Date(summary.emissionFactor.validTo).toLocaleDateString()}`}
                  </span>
                </div>
              </div>
            </div>
            <Badge variant="champagne" size="lg">
              {summary.emissionFactor.value.toFixed(3)} kgCO₂e/kWh
            </Badge>
          </div>
        </div>

        {/* Scope Breakdown */}
        {summary.breakdown && (
          <div className="mb-6">
            <h4 className="text-headline-sm text-brand-onSurface mb-4 flex items-center gap-2">
              <Leaf className="w-5 h-5 text-emerald-400" />
              Emissions by Scope
            </h4>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              {[
                { scope: 'Scope 1', value: summary.breakdown.scope1, color: '#EF4444', description: 'Direct emissions' },
                { scope: 'Scope 2', value: summary.breakdown.scope2, color: '#F59E0B', description: 'Indirect (energy)' },
                { scope: 'Scope 3', value: summary.breakdown.scope3, color: '#10B981', description: 'Value chain' },
              ].map((item) => (
                <div key={item.scope} className="p-4 rounded-xl bg-brand-surfaceContainerLow/50 border border-white/10">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-label-md text-brand-secondary uppercase tracking-wider">{item.scope}</span>
                    <div className="w-3 h-3 rounded-full" style={{ backgroundColor: item.color }} />
                  </div>
                  <div className="text-2xl font-bold font-mono text-brand-onSurface">{formatNumber(item.value, 2)}</div>
                  <div className="text-body-sm text-brand-onSurfaceVariant">{item.description}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Trend Comparison */}
        {summary.trend && (
          <div className="mb-6 p-4 rounded-xl bg-brand-surfaceContainerLow/50 border border-white/10">
            <div className="flex items-center justify-between">
              <div>
                <h4 className="text-headline-sm text-brand-onSurface">Period Comparison</h4>
                <p className="text-body-sm text-brand-onSurfaceVariant">Compared to previous period</p>
              </div>
              <div className="flex items-center gap-2">
                {trendIcon}
                <span className={classNames('font-mono font-semibold text-lg', trendDirection === 'up' && 'text-rose-400', trendDirection === 'down' && 'text-emerald-400', trendDirection === 'stable' && 'text-slate-400')}>
                  {formatPercent(summary.trend.changePercent)}
                </span>
              </div>
            </div>
            <div className="mt-4 grid grid-cols-2 gap-4">
              <div>
                <span className="text-label-sm text-brand-onSurfaceVariant">Previous Period</span>
                <div className="text-xl font-bold font-mono text-brand-onSurface">{formatNumber(summary.trend.previousPeriod, 2)} tCO₂e</div>
              </div>
              <div>
                <span className="text-label-sm text-brand-onSurfaceVariant">Current Period</span>
                <div className="text-xl font-bold font-mono text-brand-onSurface">{formatNumber(summary.totalEmissions, 2)} tCO₂e</div>
              </div>
            </div>
          </div>
        )}

        {/* Chart placeholder - would show historical emissions trend */}
        <div className="h-64 rounded-xl bg-brand-surfaceContainerLow/30 border border-white/10 flex items-center justify-center">
          <EmptyState
            title="Emissions Trend Chart"
            message="Historical emissions visualization would appear here with time-series data"
            illustration="chart"
            variant="inline"
          />
        </div>
      </CardContent>

      <CardFooter divided={false}>
        <div className="flex items-center justify-between">
          <Badge variant="default" size="sm" dot>
            <Info className="w-3 h-3" />
            All values are estimates based on {summary.emissionFactor.source} emission factor
          </Badge>
          {onExport && (
            <Button variant="outline" size="sm" onClick={onExport} icon={<Download className="w-4 h-4" />}>
              Export Report
            </Button>
          )}
        </div>
      </CardFooter>
    </Card>
  );
}

interface KPICardProps {
  label: string;
  value: string | number;
  unit?: string;
  icon: React.ReactNode;
  trend?: { value: number; direction: 'up' | 'down' | 'stable'; period: string };
  status?: 'good' | 'warning' | 'critical' | 'unknown';
  variant?: 'primary' | 'secondary' | 'neutral';
}

function KPICard({ label, value, unit, icon, trend, status, variant = 'primary' }: KPICardProps) {
  const variantColors = {
    primary: 'text-brand-secondary',
    secondary: 'text-brand-tertiary',
    neutral: 'text-brand-onSurfaceVariant',
  };

  return (
    <div className="p-4 rounded-xl bg-brand-surfaceContainerLow/50 border border-white/10 hover:border-brand-secondary/30 transition-colors">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-label-md text-brand-onSurfaceVariant uppercase tracking-wider mb-1">{label}</p>
          <div className="flex items-baseline gap-1">
            <span className={classNames('font-mono font-semibold text-2xl', variantColors[variant])}>
              {value}
            </span>
            {unit && <span className="text-body-sm text-brand-onSurfaceVariant/60 mt-1">{unit}</span>}
          </div>
        </div>
        <div className="p-2 rounded-lg bg-brand-primary/20">{icon}</div>
      </div>
      {trend && (
        <div className="mt-3 flex items-center gap-1.5">
          {trend.direction === 'up' && <TrendingUp className="w-4 h-4 text-rose-400" />}
          {trend.direction === 'down' && <TrendingDown className="w-4 h-4 text-emerald-400" />}
          {trend.direction === 'stable' && <Minus className="w-4 h-4 text-slate-400" />}
          <span className={classNames('font-mono text-body-sm font-medium', trend.direction === 'up' && 'text-rose-400', trend.direction === 'down' && 'text-emerald-400', trend.direction === 'stable' && 'text-slate-400')}>
            {trend.direction === 'up' ? '+' : ''}{trend.value.toFixed(1)}%
          </span>
          <span className="text-label-sm text-brand-onSurfaceVariant/60">{trend.period}</span>
        </div>
      )}
    </div>
  );
}
